from pathlib import Path
import subprocess
R=Path(__file__).resolve().parents[1]
prefix='local handlers={} local commands={} local messages={} local grants=0\nlocal owner={UserId=3116679300} local outsider={UserId=2}\nlocal function signal() return {Connect=function(_,f) table.insert(handlers,f) end} end\nlocal Players={PlayerAdded=signal(),GetPlayers=function() return {owner,outsider} end,GetPlayerByUserId=function(_,id) return id==owner.UserId and owner or outsider end}\nowner.Chatted=signal() outsider.Chatted=signal()\nEnum={ChatVersion={TextChatService=1,LegacyChatService=2}}\nlocal Chat={ChatVersion=1}\nlocal game={GetService=function(_,n) return n=="Players" and Players or Chat end}\nInstance={new=function() local c={Triggered=signal()} table.insert(commands,c) return c end}\n'
suffix='\nend)()\nM.register({message=function(_,s) table.insert(messages,s) end,grant=function(p,id,stars,count) assert(p==owner and id=="MeadowMouse") grants+=count end})\nhandlers[1]({UserId=2},"/monster Mossrat 6") assert(grants==0)\nhandlers[1]({UserId=3116679300},"/monster Mossrat 6") assert(grants==1)\nfor _,text in ipairs({"/monster Mossrat 0","/monster Mossrat 11","/monster Mossrat 3.5","/monster Mossrat 6 0","/monster Mossrat 6 11","/monster Other 6","/monster Mossrat 6 1 extra"}) do handlers[1]({UserId=3116679300},text) end\nassert(grants==1)\nhandlers[1]({UserId=3116679300},"/monster Mossrat 3 10") assert(grants==11)\nhandlers={} commands={} Chat.ChatVersion=2\nM.register({message=function() end,grant=function(p) assert(p==owner) grants+=1 end})\nhandlers[2]("/monster Mossrat 6") assert(grants==12)\nhandlers[3]("/monster Mossrat 6") assert(grants==12)\nprint("OWNER_CHAT_AUTH_PASS: modern and legacy, outsider rejection, input bounds")\n'
source=(R/"src/server/OperatorCommands.luau").read_text(encoding="utf8")
path=R/".tools/test_owner_chat.luau"
path.write_text(prefix+"local M=(function()\n"+source+suffix,encoding="utf8")
subprocess.run([str(R/".tools/luau/luau.exe"),'.tools/test_owner_chat.luau'],check=True,cwd=R)
